<?php
declare(strict_types=1);
session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();
$role=(string)$_SESSION['role'];$roles=['director','sub_director','headteacher','head_academic','assistant_academic','examination_officer','teacher'];if(!in_array($role,$roles,true)){http_response_code(403);exit('Your role cannot access grading scales.');}
$uid=(int)$_SESSION['user_id'];$q=db()->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();$ids=array_map('intval',array_column($schools,'id'));if(!$ids){http_response_code(403);exit('No school is linked to your account.');}$school=(int)($_GET['school_id']??$ids[0]);if(!in_array($school,$ids,true)){http_response_code(403);exit('That school is outside your access.');}
$year=(int)($_GET['academic_year']??date('Y'));$q=db()->prepare('SELECT id,name FROM school_classes WHERE school_id=? ORDER BY name');$q->execute([$school]);$classes=$q->fetchAll();$writer=in_array($role,['director','sub_director','headteacher'],true);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Grading scales · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/app.js"></script><script defer src="assets/grading-scales.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Academics <span>/</span> Grading scales</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e((string)($_SESSION['name']??'User'))?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">ACADEMIC POLICY</div><h1>Grading scales</h1><p class="muted">Define grade bands by academic year. Class scales override school-wide scales.</p></div></section><form method="get" class="form-grid"><div><label for="gs-school">School</label><select id="gs-school" name="school_id"><?php foreach($schools as $s):?><option value="<?=$s['id']?>"<?=(int)$s['id']===$school?' selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></div><div><label for="gs-year">Academic year</label><input id="gs-year" type="number" min="2000" max="2100" name="academic_year" value="<?=$year?>"></div><button class="button" type="submit">Load scales</button></form>
<?php if($writer):?><section class="note-create"><h2>Create a draft</h2><form data-grading-create><input type="hidden" name="school_id" value="<?=$school?>"><div class="form-grid"><div><label for="gs-name">Scale name</label><input id="gs-name" name="name" maxlength="120" required></div><div><label for="gs-create-year">Academic year</label><input id="gs-create-year" name="academic_year" type="number" min="2000" max="2100" value="<?=$year?>" required></div><div><label for="gs-class">Class (optional)</label><select id="gs-class" name="class_id"><option value="">All classes</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="form-span"><label for="gs-bands">Grade bands as JSON</label><textarea id="gs-bands" name="bands" rows="8" required></textarea><p class="muted">Enter your school's approved labels and inclusive percentage ranges. No grading cutoffs are supplied.</p></div></div><button class="button primary" type="submit">Save draft</button></form></section><?php endif;?>
<section class="content-section"><div class="section-heading"><h2>Scales for <?=$year?></h2></div><div data-grading-list data-school="<?=$school?>" data-year="<?=$year?>" data-writer="<?=$writer?'1':'0'?>" data-csrf="<?=e(csrf_token())?>" aria-live="polite"><p class="muted">Loading scales…</p></div></section><footer class="page-footer">ShuleLite · School grading policy</footer></div></main></div></body></html>
